#include "all_your_base.h"
#include <cstdio>
#include <random>
#include <stdexcept>
#include <vector>

using all_your_base::convert;
using V = std::vector<unsigned int>;

static int failures = 0;
static void check(bool ok, const char* what) {
    if (!ok) { std::printf("FAIL: %s\n", what); ++failures; }
}

// strip leading zeros so inputs and outputs are comparable
static V strip(V v) {
    std::size_t i = 0;
    while (i < v.size() && v[i] == 0) ++i;
    return V(v.begin() + static_cast<std::ptrdiff_t>(i), v.end());
}

int main() {
    std::mt19937 rng(12345);

    // Round trip over many random base pairs and lengths, incl. large bases.
    for (int iter = 0; iter < 4000; ++iter) {
        unsigned in_base = 2 + rng() % 255;      // 2..256
        unsigned out_base = 2 + rng() % 255;
        std::size_t len = 1 + rng() % 40;
        V digits(len);
        for (auto& d : digits) d = rng() % in_base;
        V mid = convert(in_base, digits, out_base);
        for (unsigned d : mid) {
            check(d < out_base, "output digit within output base");
            check(d <= 65535u, "no garbage digits");
        }
        V back = convert(out_base, mid, in_base);
        check(back == strip(digits), "round trip preserves value");
        for (unsigned d : back) check(d < in_base, "back digit within input base");
    }

    // Very long input: 4000 binary digits all 1s -> base 10, then back.
    V ones(4000, 1u);
    V dec = convert(2, ones, 10);
    for (unsigned d : dec) check(d < 10, "decimal digit range");
    check(convert(10, dec, 2) == ones, "long binary round trip");

    // Value not truncated: 2^64 in base 2 (1 followed by 64 zeros) must not be 0.
    V big(65, 0u); big[0] = 1;
    V bigdec = convert(2, big, 10);
    check(!bigdec.empty(), "2^64 does not collapse to zero");
    check(convert(10, bigdec, 2) == big, "2^64 round trip");

    // Base 256 <-> base 2 with max digits.
    V bytes{255u, 0u, 128u};
    V bits = convert(256, bytes, 2);
    check(convert(2, bits, 256) == bytes, "base 256 round trip");

    // Zero handling in any base.
    check(convert(10, V{0u}, 7).empty(), "single zero -> empty");
    check(convert(7, V{0u, 0u, 0u}, 16).empty(), "multiple zeros -> empty");
    check(convert(16, V{}, 3).empty(), "empty input -> empty output");

    // Leading zeros stripped.
    check(convert(7, V{0u, 6u, 0u}, 10) == V{4u, 2u}, "leading zeros stripped");

    // Invalid bases throw even with empty digits.
    for (unsigned b : {0u, 1u}) {
        bool threw = false;
        try { convert(b, V{}, 10); } catch (const std::invalid_argument&) { threw = true; }
        check(threw, "invalid input base throws");
        threw = false;
        try { convert(10, V{1u}, b); } catch (const std::invalid_argument&) { threw = true; }
        check(threw, "invalid output base throws");
    }

    // Digit equal to / above base throws; max valid digit does not.
    for (unsigned b = 2; b <= 36; ++b) {
        bool threw = false;
        try { convert(b, V{b}, 10); } catch (const std::invalid_argument&) { threw = true; }
        check(threw, "digit == base throws");
        threw = false;
        try { convert(b, V{b - 1u}, 10); } catch (const std::invalid_argument&) { threw = true; }
        check(!threw, "digit == base-1 allowed");
        threw = false;
        try { convert(b, V{0u, b + 5u}, 10); } catch (const std::invalid_argument&) { threw = true; }
        check(threw, "digit > base throws");
    }

    std::printf(failures == 0 ? "ALL EDGE CASES PASSED\n" : "%d EDGE FAILURES\n", failures);
    return failures == 0 ? 0 : 1;
}
